nextflow_process {

    name "Test Process OARFISH_READPROJECTIONMODE"
    script "../main.nf"
    process "OARFISH_READPROJECTIONMODE"

    tag "modules"
    tag "modules_nfcore"
    tag "oarfish"
    tag "oarfish/readprojectionmode"


    test("pacbio - fastq") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/fastq/alz.ccs.fastq', checkIfExists: true),
                    'pac-bio'
                ]
                input[1] = [
                    [ id:'test_fasta' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'test_gtf' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ['meta_info'])).match() }
            )
        }
    }

